// 1. Empresa do grupo vem do formulário, não da IA
let empresa = null;
try {
  const j = $('Recebe Nota Fiscal').first().json;
  empresa = j['Empresa do Grupo'] ?? j['Empresa_do_Grupo'] ?? null;
} catch (e) {
  empresa = null;
}

// 2. Acesso protegido à resposta da IA
const raw = $input.item?.json?.content?.[0]?.text;

if (!raw) {
  return {
    json: {
      erro: true,
      revisao_parcial: false,
      empresa,
      mensagem: "Resposta da IA em formato inesperado. Requer revisão manual.",
      texto_bruto: JSON.stringify($input.item?.json ?? {})
    }
  };
}

// 3. Limpeza de formatação acidental
let cleaned = raw.replace(/```json\n?/g, '').replace(/```/g, '').trim();
const match = cleaned.match(/\{[\s\S]*\}/);
if (match) cleaned = match[0];

let data;
try {
  data = JSON.parse(cleaned);
} catch (error) {
  return {
    json: {
      erro: true,
      revisao_parcial: false,
      empresa,
      mensagem: "Não foi possível extrair os dados da nota automaticamente. Requer revisão manual.",
      texto_bruto: raw
    }
  };
}

// 4. Normaliza "null" em string e vazios para null de verdade
const limpar = (v) => {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  if (s === '' || s.toLowerCase() === 'null') return null;
  return s;
};

const soDigitos = (v) => {
  const s = limpar(v);
  if (s === null) return null;
  const d = s.replace(/\D/g, '');
  return d === '' ? null : d;
};

// 5. Campos obrigatórios para o lançamento
const campos = {
  numero_nota: limpar(data.numero_nota),
  valor: limpar(data.valor),
  vencimento: limpar(data.vencimento),
  centro_de_custo: limpar(data.centro_de_custo)
};

const camposFaltando = Object.keys(campos).filter(c => campos[c] === null);

// 6. Identificação das partes: informativa, não bloqueia o lançamento
const partes = {
  fornecedor: limpar(data.fornecedor),
  cnpj_fornecedor: soDigitos(data.cnpj_fornecedor),
  empresa_destinataria: limpar(data.empresa_destinataria),
  cnpj_destinatario: soDigitos(data.cnpj_destinatario)
};

// 7. Nenhum campo identificado: provavelmente não é uma nota fiscal
if (camposFaltando.length === 4) {
  return {
    json: {
      erro: true,
      revisao_parcial: false,
      empresa,
      mensagem: "Nenhum dado de nota fiscal foi identificado no documento. Verifique se o arquivo enviado é realmente uma nota fiscal.",
      texto_bruto: raw
    }
  };
}

// 8. Extração parcial: a nota segue para lançamento, marcada para conferência
const parcial = camposFaltando.length > 0;

return {
  json: {
    erro: false,
    revisao_parcial: parcial,
    campos_faltando: camposFaltando,
    mensagem: parcial
      ? `Extração parcial. Campos não identificados: ${camposFaltando.join(', ')}. Lançar com status "Conferência pendente".`
      : null,
    empresa,
    ...campos,
    ...partes
  }
};

const item = $input.item.json;

let empresa = null;
try {
  const j = $('Recebe Nota Fiscal').first().json;
  empresa = j['Empresa do Grupo'] ?? j['Empresa_do_Grupo'] ?? null;
} catch (e) {
  empresa = null;
}

let mensagemErro = "Falha técnica não especificada";
if (typeof item.error === 'string') {
  mensagemErro = item.error;
} else if (item.error?.message) {
  mensagemErro = item.error.message;
} else if (item.message) {
  mensagemErro = item.message;
}

const etapa = item.etapa || "desconhecida";

const acoes = {
  "Extração do PDF": "Arquivo possivelmente corrompido, protegido por senha ou digitalizado como imagem. Solicitar reenvio ao fornecedor.",
  "Chamada à IA": "Indisponibilidade da API ou credencial vencida. Não reenviar a nota — acionar o responsável técnico."
};

return {
  json: {
    erro: true,
    revisao_parcial: false,
    empresa,
    etapa,
    mensagem: `Falha técnica na etapa: ${etapa}. Detalhe: ${mensagemErro}`,
    acao_recomendada: acoes[etapa] || "Acionar o responsável técnico."
  }
};
